import { WaveformType } from './types';

interface ActiveVoice {
  oscillator: OscillatorNode;
  gainNode: GainNode;
  filterNode: BiquadFilterNode;
}

const MAX_POLYPHONY = 16;

class SoundEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private activeVoices: Map<string, ActiveVoice> = new Map();
  private currentWaveform: WaveformType = 'triangle';
  private currentVolume: number = 0.7;

  private initContext(): AudioContext {
    if (!this.ctx) {
      const AudioCtxClass =
        window.AudioContext ||
        (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      this.ctx = new AudioCtxClass();

      this.masterGain = this.ctx.createGain();
      this.masterGain.gain.setValueAtTime(this.currentVolume, this.ctx.currentTime);
      this.masterGain.connect(this.ctx.destination);
    }

    if (this.ctx.state === 'suspended') {
      this.ctx.resume().catch((err) => {
        console.warn('AudioContext resume was prevented or failed:', err);
      });
    }

    return this.ctx;
  }

  public setVolume(volume: number): void {
    const clampedVolume = Math.max(0, Math.min(1, volume));
    this.currentVolume = clampedVolume;

    if (this.ctx && this.masterGain) {
      const now = this.ctx.currentTime;
      this.masterGain.gain.cancelScheduledValues(now);
      this.masterGain.gain.linearRampToValueAtTime(clampedVolume, now + 0.05);
    }
  }

  public setWaveform(waveform: WaveformType): void {
    this.currentWaveform = waveform;
  }

  public playNote(note: string, frequency: number, customWaveform?: WaveformType): void {
    const ctx = this.initContext();
    const waveform = customWaveform || this.currentWaveform;

    // ポリフォニー制限: 上限に達した場合、最も古いボイスを解放
    if (this.activeVoices.size >= MAX_POLYPHONY && !this.activeVoices.has(note)) {
      const oldestKey = this.activeVoices.keys().next().value;
      if (oldestKey) {
        this.stopNote(oldestKey);
      }
    }

    // 既に同一音階が発音中の場合は一度減衰停止
    if (this.activeVoices.has(note)) {
      this.stopNote(note);
    }

    const now = ctx.currentTime;

    const osc = ctx.createOscillator();
    osc.type = waveform;
    osc.frequency.setValueAtTime(frequency, now);

    // 自然なピアノ調の温かみを加えるローパスフィルタ
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    const cutoffFreq = Math.min(frequency * 5, 8000);
    filter.frequency.setValueAtTime(cutoffFreq, now);
    filter.Q.setValueAtTime(1, now);

    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.0001, now);

    // ADSR エンベロープ設定
    const attackTime = 0.015;
    const decayTime = 0.18;
    const sustainLevel = 0.55;

    gain.gain.exponentialRampToValueAtTime(1.0, now + attackTime);
    gain.gain.exponentialRampToValueAtTime(sustainLevel, now + attackTime + decayTime);

    osc.connect(filter);
    filter.connect(gain);
    if (this.masterGain) {
      gain.connect(this.masterGain);
    }

    // 再生終了イベントで確実にリソースを切断・解放
    osc.onended = () => {
      try {
        osc.disconnect();
        filter.disconnect();
        gain.disconnect();
      } catch {
        // すでに切断済みの場合は無視
      }
    };

    osc.start(now);

    this.activeVoices.set(note, {
      oscillator: osc,
      gainNode: gain,
      filterNode: filter,
    });
  }

  public stopNote(note: string): void {
    const voice = this.activeVoices.get(note);
    if (!voice || !this.ctx) return;

    this.activeVoices.delete(note);

    const { oscillator, gainNode } = voice;
    const now = this.ctx.currentTime;
    const releaseTime = 0.25;

    try {
      gainNode.gain.cancelScheduledValues(now);
      gainNode.gain.setValueAtTime(Math.max(gainNode.gain.value, 0.0001), now);
      gainNode.gain.exponentialRampToValueAtTime(0.0001, now + releaseTime);

      oscillator.stop(now + releaseTime + 0.05);
    } catch {
      try {
        oscillator.stop();
      } catch {
        // 何もしない
      }
    }
  }

  public stopAllNotes(): void {
    const activeKeys = Array.from(this.activeVoices.keys());
    for (const key of activeKeys) {
      this.stopNote(key);
    }
  }
}

export const soundEngine = new SoundEngine();

import { FC, PointerEvent } from 'react';
import { KeyboardProps, PIANO_KEYS, PianoKeyItem } from '../types';

const Keyboard: FC<KeyboardProps> = ({
  activeNotes = new Set<string>(),
  onPlayNote,
  onStopNote,
  showKeyLabels = true,
}) => {
  const whiteKeys = PIANO_KEYS.filter((k) => !k.isBlack);
  const blackKeys = PIANO_KEYS.filter((k) => k.isBlack);

  const handlePointerDown = (keyItem: PianoKeyItem, e: PointerEvent<HTMLButtonElement>) => {
    e.preventDefault();
    onPlayNote?.(keyItem);
  };

  const handlePointerUp = (keyItem: PianoKeyItem, e: PointerEvent<HTMLButtonElement>) => {
    e.preventDefault();
    onStopNote?.(keyItem);
  };

  const handlePointerEnter = (keyItem: PianoKeyItem, e: PointerEvent<HTMLButtonElement>) => {
    if (e.buttons > 0) {
      onPlayNote?.(keyItem);
    }
  };

  const handlePointerLeave = (keyItem: PianoKeyItem, _e: PointerEvent<HTMLButtonElement>) => {
    if (activeNotes.has(keyItem.note)) {
      onStopNote?.(keyItem);
    }
  };

  const handlePointerCancel = (keyItem: PianoKeyItem, e: PointerEvent<HTMLButtonElement>) => {
    e.preventDefault();
    onStopNote?.(keyItem);
  };

  return (
    <div className="keyboard-container">
      <div className="piano-keyboard" role="group" aria-label="ピアノ鍵盤">
        {/* 白鍵行 */}
        <div className="white-keys-row">
          {whiteKeys.map((keyItem) => {
            const isActive = activeNotes.has(keyItem.note);
            const className = isActive ? 'white-key key-active' : 'white-key';

            return (
              <button
                key={keyItem.note}
                type="button"
                className={className}
                onPointerDown={(e) => handlePointerDown(keyItem, e)}
                onPointerUp={(e) => handlePointerUp(keyItem, e)}
                onPointerEnter={(e) => handlePointerEnter(keyItem, e)}
                onPointerLeave={(e) => handlePointerLeave(keyItem, e)}
                onPointerCancel={(e) => handlePointerCancel(keyItem, e)}
                aria-label={`${keyItem.pitchName} (${keyItem.note})`}
                aria-pressed={isActive}
              >
                {showKeyLabels && (
                  <div className="key-label">
                    <span className="key-shortcut">{keyItem.keyBinding.toUpperCase()}</span>
                    <span className="note-name">{keyItem.pitchName}</span>
                  </div>
                )}
              </button>
            );
          })}
        </div>

        {/* 黒鍵行（CSSのnth-childで配置） */}
        <div className="black-keys-row">
          {blackKeys.map((keyItem) => {
            const isActive = activeNotes.has(keyItem.note);
            const className = isActive ? 'black-key key-active' : 'black-key';

            return (
              <button
                key={keyItem.note}
                type="button"
                className={className}
                onPointerDown={(e) => handlePointerDown(keyItem, e)}
                onPointerUp={(e) => handlePointerUp(keyItem, e)}
                onPointerEnter={(e) => handlePointerEnter(keyItem, e)}
                onPointerLeave={(e) => handlePointerLeave(keyItem, e)}
                onPointerCancel={(e) => handlePointerCancel(keyItem, e)}
                aria-label={`${keyItem.pitchName} (${keyItem.note})`}
                aria-pressed={isActive}
              >
                {showKeyLabels && (
                  <div className="key-label">
                    <span className="key-shortcut">{keyItem.keyBinding.toUpperCase()}</span>
                    <span className="note-name">{keyItem.pitchName}</span>
                  </div>
                )}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default Keyboard;

import { FC, useState, useEffect, useCallback, useRef } from 'react';
import Keyboard from './components/Keyboard';
import Controls from './components/Controls';
import {
  WaveformType,
  PianoKeyItem,
  PlayedNote,
  PIANO_KEYS,
  DemoSongNote,
} from './types';
import { soundEngine } from './audio';
import './index.css';

const App: FC = () => {
  const [waveform, setWaveform] = useState<WaveformType>('triangle');
  const [volume, setVolume] = useState<number>(0.7);
  const [showKeyLabels, setShowKeyLabels] = useState<boolean>(true);
  const [activeNotes, setActiveNotes] = useState<Set<string>>(new Set());
  const [playedHistory, setPlayedHistory] = useState<PlayedNote[]>([]);
  const [lastPlayedNote, setLastPlayedNote] = useState<PianoKeyItem | null>(null);
  const [isDemoPlaying, setIsDemoPlaying] = useState<boolean>(false);
  const [currentDemoTitle, setCurrentDemoTitle] = useState<string>('');

  const demoTimeoutsRef = useRef<number[]>([]);

  // 音色変更ハンドラ
  const handleWaveformChange = (newWaveform: WaveformType) => {
    setWaveform(newWaveform);
    soundEngine.setWaveform(newWaveform);
  };

  // 音量変更ハンドラ
  const handleVolumeChange = (newVolume: number) => {
    setVolume(newVolume);
    soundEngine.setVolume(newVolume);
  };

  // キーラベル表示切り替え
  const handleToggleKeyLabels = () => {
    setShowKeyLabels((prev) => !prev);
  };

  // ノート発音処理
  const handlePlayNote = useCallback((keyItem: PianoKeyItem) => {
    soundEngine.playNote(keyItem.note, keyItem.frequency);

    setActiveNotes((prev) => {
      const next = new Set(prev);
      next.add(keyItem.note);
      return next;
    });

    setLastPlayedNote(keyItem);

    const now = new Date();
    const timeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}`;
    const newPlayedNote: PlayedNote = {
      id: crypto.randomUUID(),
      note: keyItem.note,
      pitchName: keyItem.pitchName,
      timestamp: timeStr,
    };

    setPlayedHistory((prev) => [newPlayedNote, ...prev.slice(0, 11)]);
  }, []);

  // ノート停止処理
  const handleStopNote = useCallback((keyItem: PianoKeyItem) => {
    soundEngine.stopNote(keyItem.note);

    setActiveNotes((prev) => {
      const next = new Set(prev);
      next.delete(keyItem.note);
      return next;
    });
  }, []);

  // 全デモ停止
  const stopDemo = useCallback(() => {
    demoTimeoutsRef.current.forEach((timeoutId) => clearTimeout(timeoutId));
    demoTimeoutsRef.current = [];
    soundEngine.stopAllNotes();
    setActiveNotes(new Set());
    setIsDemoPlaying(false);
    setCurrentDemoTitle('');
  }, []);

  // デモ曲再生
  const playDemoSong = (song: DemoSongNote[], title: string) => {
    stopDemo();
    setIsDemoPlaying(true);
    setCurrentDemoTitle(title);

    const keyMap = new Map<string, PianoKeyItem>();
    PIANO_KEYS.forEach((k) => keyMap.set(k.note, k));

    let maxEndTime = 0;

    song.forEach((item) => {
      const targetKey = keyMap.get(item.note);
      if (!targetKey) return;

      const playTimeout = window.setTimeout(() => {
        handlePlayNote(targetKey);
      }, item.delay);

      const stopTimeout = window.setTimeout(() => {
        handleStopNote(targetKey);
      }, item.delay + item.duration);

      demoTimeoutsRef.current.push(playTimeout, stopTimeout);

      if (item.delay + item.duration > maxEndTime) {
        maxEndTime = item.delay + item.duration;
      }
    });

    const finishTimeout = window.setTimeout(() => {
      setIsDemoPlaying(false);
      setCurrentDemoTitle('');
    }, maxEndTime + 200);

    demoTimeoutsRef.current.push(finishTimeout);
  };

  // PCキーボード押下イベント
  useEffect(() => {
    const keyMapByBinding = new Map<string, PianoKeyItem>();
    PIANO_KEYS.forEach((k) => keyMapByBinding.set(k.keyBinding.toLowerCase(), k));

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.repeat || e.ctrlKey || e.metaKey || e.altKey) return;
      const key = e.key.toLowerCase();
      const targetKey = keyMapByBinding.get(key);
      if (targetKey && !activeNotes.has(targetKey.note)) {
        handlePlayNote(targetKey);
      }
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      const key = e.key.toLowerCase();
      const targetKey = keyMapByBinding.get(key);
      if (targetKey) {
        handleStopNote(targetKey);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [activeNotes, handlePlayNote, handleStopNote]);

  // コンポーネント破棄時に音源停止
  useEffect(() => {
    return () => {
      stopDemo();
    };
  }, [stopDemo]);

  return (
    <div className="app-container">
      {/* ヘッダー */}
      <header className="header">
        <h1 className="header-title">Web Studio Piano</h1>
        <p className="header-subtitle">
          Web Audio API搭載・1オクターブ本格演奏ピアノ（PCキーボード＆タッチ対応）
        </p>
      </header>

      {/* コントロールパネル */}
      <Controls
        waveform={waveform}
        volume={volume}
        showKeyLabels={showKeyLabels}
        isDemoPlaying={isDemoPlaying}
        currentDemoTitle={currentDemoTitle}
        onWaveformChange={handleWaveformChange}
        onVolumeChange={handleVolumeChange}
        onToggleKeyLabels={handleToggleKeyLabels}
        onPlayDemo={playDemoSong}
        onStopDemo={stopDemo}
      />

      {/* 鍵盤ユニット */}
      <Keyboard
        activeNotes={activeNotes}
        onPlayNote={handlePlayNote}
        onStopNote={handleStopNote}
        showKeyLabels={showKeyLabels}
      />

      {/* PCキーボード操作案内 */}
      <div className="shortcut-guide">
        <strong>PCキーボードショートカット:</strong> 白鍵 [ A S D F G H J K ] ／ 黒鍵 [ W E T Y U ]
        <br />
        マウス押下、タッチスライド、複数キー同時押しによる和音演奏にも対応しています。
      </div>

      {/* 演奏履歴 & 直近の音符 */}
      <section className="history-section" aria-label="演奏履歴">
        <div className="history-header">
          <h2 className="history-title">演奏ログ</h2>
          {lastPlayedNote && (
            <span className="history-last-note">
              直前の音: <strong>{lastPlayedNote.pitchName}</strong> ({lastPlayedNote.note})
            </span>
          )}
        </div>

        <div className="history-chips">
          {playedHistory.length === 0 ? (
            <span className="history-empty">
              鍵盤を押すかPCキーボードを叩いて音を鳴らしてみましょう
            </span>
          ) : (
            playedHistory.map((item) => (
              <div key={item.id} className="history-chip">
                <span>{item.pitchName}</span>
                <span className="history-note-name">{item.note}</span>
              </div>
            ))
          )}
        </div>
      </section>
    </div>
  );
};

export default App;
